import {beforeFlags3AcceptanceManifest} from "./question-flags3-acceptance-test-support";
import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  ANSWER_CHOICE_TIMING_REGISTRY,
  QUESTION_BANK_BATCH2B_REVISIONS,
  QUESTION_BANK_BATCH2B_ROUND2_REVISIONS,
  QUESTION_BANK_BATCH2B_ROUND2_SOURCE_RELEASE as source,
  SYNTHETIC_CLINICAL_RELEASE as live,
} from "./index";
import { QUESTION_SHIP_MANIFEST as manifest, type QuestionShipManifest } from "./question-ship-manifest";
import { QUESTION_FLAGS2_ROUND3_SOURCE_RELEASE as acceptedFlags2 } from "./question-flags2-round3-20261105";
import { beforeN3AcceptanceRelease } from "./question-new-n3-acceptance-test-support";

const read = (path: string): string => readFileSync(new URL("../../../" + path, import.meta.url), "utf8");
const sha = (text: string): string => createHash("sha256").update(text).digest("hex");
const intake = JSON.parse(read("tools/question-quality/fixtures/batch2b-acceptance-before-20261105.json")) as {
  release: typeof live;
  manifest: QuestionShipManifest;
  packet: Array<{ id: string; caseId: string; nodeId: string; after: { variantId: string } }>;
  review: Array<{ id: string; verdict: string }>;
};
const changes = JSON.parse(read("tools/question-quality/batch2b-acceptance-changes-20261105.json")) as {
  acceptedRows: QuestionShipManifest["accepted"];
  holds: Array<{ id: string; classification: string; accepted: boolean; itemEdited: boolean; claimIds: string[] }>;
  digestReconciliation: {
    count: number; captures: number;
    rows: Array<{ capture: string; path: string; expected: string; actual: string }>;
    files: Array<{ path: string; beforeSha256: string; currentSha256: string }>;
  };
};
const acceptedIds = [
  "B2B01", "B2B02", "B2B06", "B2B08", "B2B09", "B2B10", "B2B17", "B2B21",
  "B2B23", "B2B24", "B2B25", "B2B30", "B2B33", "B2B39", "B2B40", "B2B42",
];
const heldIds = ["B2B32", "F13"];
const ownRows = manifest.accepted.filter(row => row.sourceView === "batch2b-round2");
const saved = (value: unknown): string | undefined => JSON.stringify(value);
const nodeFor = (release: typeof live, caseId: string, nodeId: string) =>
  release.cases.find(cs => cs.id === caseId)!.decisionNodes.find(node => node.id === nodeId)!;

describe("batch 2b manager-directed exact-version acceptance", () => {
  it("accepts exactly the sixteen unconditional PASS tuples and their reviewed headers", () => {
    expect(ownRows.map(row => row.acceptanceId).sort()).toEqual(acceptedIds.slice().sort());
    expect(ownRows).toEqual(changes.acceptedRows);
    expect(new Set(ownRows.map(row => row.caseId)).size).toBe(16);
    for (const row of ownRows) {
      expect(intake.review.find(item => item.id === row.acceptanceId)?.verdict).toBe("PASS");
      expect(row.decision).toBe("docs/research/question-bank-batch2b-manager-decision-20261105.md");
      expect(manifest.headerSources[row.caseId]).toBe("batch2b-round2");
    }
  });

  it.each(acceptedIds)("projects %s exactly, with its historical timing tuple and draft review status", id => {
    const row = ownRows.find(row => row.acceptanceId === id)!;
    const current = live.cases.find(cs => cs.id === row.caseId)!;
    const authored = source.cases.find(cs => cs.id === row.caseId)!;
    const node = nodeFor(live, row.caseId, row.nodeId);
    expect(node).toEqual(nodeFor(source, row.caseId, row.nodeId));
    expect(node).toMatchObject({ questionVariantId: row.questionVariantId, primaryConceptId: row.conceptId, shuffleAnswers: true });
    expect(current.presentation).toBe(authored.presentation);
    expect(current.chiefComplaint).toBe(authored.chiefComplaint);
    expect(current.approvedInstantiationProfiles).toEqual(authored.approvedInstantiationProfiles);
    const revision = [...QUESTION_BANK_BATCH2B_REVISIONS, ...QUESTION_BANK_BATCH2B_ROUND2_REVISIONS]
      .find(candidate => candidate.questionVariantId === row.questionVariantId)!;
    expect(revision.question.reviewStatus).toBe("needs_clinician_review");
    expect(revision.question.lastClinicianReview).toBeNull();
    const timings = ANSWER_CHOICE_TIMING_REGISTRY.filter(timing => timing.caseId === row.caseId &&
      timing.nodeId === row.nodeId && timing.questionVariantId === row.questionVariantId);
    expect(timings).toHaveLength(1);
    const classification = timings[0]!.classification;
    if (classification.kind === "test_choices") {
      expect(classification.choices).toHaveLength(node.answerChoices.length);
      for (const choice of node.answerChoices) {
        expect(classification.choices.find(timing => timing.choiceId === choice.id)?.choiceLabel).toBe(choice.label);
      }
    }
  });

  it("keeps both source-held PASS keys live without editing or accepting either draft", () => {
    expect(changes.holds.map(row => row.id).sort()).toEqual(heldIds.slice().sort());
    for (const hold of changes.holds) {
      expect(hold).toMatchObject({ classification: "hold_on_key", accepted: false, itemEdited: false });
      expect(hold.claimIds.length).toBeGreaterThan(0);
      expect(ownRows.some(row => row.acceptanceId === hold.id)).toBe(false);
      const packet = intake.packet.find(row => row.id === hold.id)!;
      expect(saved(nodeFor(live, packet.caseId, packet.nodeId)))
        .toBe(saved(nodeFor(intake.release, packet.caseId, packet.nodeId)));
    }
  });

  it("parks all twenty-two REVISE drafts, preserving fallback except the later exact flags2 whole-case acceptance", () => {
    const revise = intake.review.filter(row => row.verdict === "REVISE");
    expect(revise).toHaveLength(22);
    for (const item of revise) {
      const packet = intake.packet.find(row => row.id === item.id)!;
      if(manifest.replacements.some(r=>r.replaces===packet.caseId)){
        expect(live.cases.find(c=>c.id===packet.caseId)).toEqual(acceptedFlags2.cases.find(c=>c.id===packet.caseId));
      }else{
        expect(saved(nodeFor(live, packet.caseId, packet.nodeId)))
          .toBe(saved(nodeFor(intake.release, packet.caseId, packet.nodeId)));
      }
      expect(manifest.accepted.some(row => row.caseId === packet.caseId && row.nodeId === packet.nodeId &&
        row.questionVariantId === packet.after.variantId)).toBe(false);
    }
    const g03 = intake.packet.find(row => row.id === "B2B36")!;
    expect(nodeFor(live, g03.caseId, g03.nodeId).questionVariantId)
      .toBe("question.palpable-breast.negative-mammogram-targeted-us.v1.r4");
  });

  it("preserves every historical legacy binding and existing non-N2 acceptance", () => {
    expect(manifest.legacyBindings).toEqual(intake.manifest.legacyBindings);
    for (const old of intake.manifest.accepted.filter(row => !row.acceptanceId.startsWith("review.n2."))) {
      expect(beforeFlags3AcceptanceManifest(manifest).accepted.find(row => row.acceptanceId === old.acceptanceId)).toEqual(old);
    }
    for (const old of intake.release.concepts) {
      expect(live.concepts.find(row => row.id === old.id)).toEqual(old);
    }
    expect(beforeN3AcceptanceRelease(live).cases).toHaveLength(intake.release.cases.length);
  });

  it("composes B2B24 with the exact old second node and gate, without importing a neighboring draft", () => {
    const row = ownRows.find(row => row.acceptanceId === "B2B24")!;
    const current = live.cases.find(cs => cs.id === row.caseId)!;
    const old = intake.release.cases.find(cs => cs.id === row.caseId)!;
    expect(current.decisionNodes).toHaveLength(2);
    expect(current.decisionNodes[0]).toEqual(nodeFor(source, row.caseId, row.nodeId));
    expect(saved(current.decisionNodes[1])).toBe(saved(old.decisionNodes[1]));
    expect(saved(current.decisionNodes[0]!.resultGateAfter)).toBe(saved(old.decisionNodes[0]!.resultGateAfter));
    const exhibit = current.decisionNodes[0]!.exhibit!;
    expect(exhibit.kind).toBe("image");
    if (exhibit.kind === "image") expect(existsSync(new URL("../../../apps/player/public/" + exhibit.assetPath, import.meta.url))).toBe(true);
    const preview = JSON.parse(read("docs/research/question-bank-batch2b-composed-preview-20261105.json")) as {
      label: string; acceptedCount: number; mixedCases: Array<{ caseId: string; sequenceLimitation: string }>;
      cases: Array<{ caseId: string; nodes: Array<{ Options: string[] }> }>;
    };
    expect(preview.label).toContain("key shown first for review only");
    expect(preview.acceptedCount).toBe(16);
    expect(preview.mixedCases).toHaveLength(1);
    expect(preview.mixedCases[0]!.caseId).toBe(row.caseId);
    expect(preview.mixedCases[0]!.sequenceLimitation).toContain("rehearsed/easy");
    expect(preview.cases.find(cs => cs.caseId === row.caseId)!.nodes.every(node => node.Options[0]!.startsWith("**KEY:** "))).toBe(true);
  });

  it("reconciles only the three receipt-authorized scalar hashes in the two captures", () => {
    expect(changes.digestReconciliation.count).toBe(3);
    expect(changes.digestReconciliation.captures).toBe(2);
    expect(changes.digestReconciliation.rows).toHaveLength(3);
    for (const capture of changes.digestReconciliation.files) {
      const current = read(capture.path);
      expect(sha(current)).toBe(capture.currentSha256);
      let reversed = current;
      for (const row of changes.digestReconciliation.rows.filter(row => row.capture === capture.path)) {
        const needle = JSON.stringify(row.path) + ": " + JSON.stringify(row.actual);
        expect(reversed.split(needle)).toHaveLength(2);
        reversed = reversed.replace(needle, JSON.stringify(row.path) + ": " + JSON.stringify(row.expected));
        expect(sha(read(row.path))).toBe(row.actual);
      }
      // Byte-for-byte reversal proves that no other capture field was altered.
      expect(sha(reversed)).toBe(capture.beforeSha256);
    }
  });
});

import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { describe, expect, it } from "vitest";
import {
  QUESTION_NEW_N2_ROUND2_PRE_RELEASE as before,
  QUESTION_BANK_BATCH2B_ROUND2_SOURCE_RELEASE as after,
  QUESTION_BANK_BATCH2B_ROUND2_REVISIONS as revisions,
  QUESTION_BANK_BATCH2B_ROUND2_AUTHORING_CONCEPTS as concepts,
  QUESTION_BANK_BATCH2B_ROUND2_CLAIMS as claims,
  QUESTION_BANK_BATCH2B_ROUND2_PRE_TIMING_ENTRIES as oldTimings,
  QUESTION_BANK_BATCH2B_ROUND2_TIMING_ENTRIES as timings,
  ANSWER_CHOICE_TIMING_REGISTRY,
  applyQuestionBankBatch2bRound2Revisions,
  QUESTION_QUALITY_CLINICAL_APPROVALS,
  SYNTHETIC_CLINICAL_RELEASE as live,
} from "./index";
import { syntheticClinicalReleaseSchema } from "./schema";
import { QUESTION_SHIP_MANIFEST } from "./question-ship-manifest";
const capture=JSON.parse(readFileSync(new URL("../../../tools/question-quality/fixtures/question-bank-batch2b-round2-before-20261104.json",import.meta.url),"utf8")) as {files:Record<string,string>;approvals:unknown;packet:Array<{id:string;caseId:string;nodeId:string}>};
const clone=<T>(v:T):T=>JSON.parse(JSON.stringify(v)) as T;

describe("batch 2b round-two candidate safety and compatibility",()=>{
  it("changes only the thirty-eight returned/omitted nodes in thirty-seven retained cases",()=>{
    expect(revisions).toHaveLength(38);expect(new Set(revisions.map(r=>r.caseId)).size).toBe(37);
    expect(after.cases).toHaveLength(before.cases.length);
    for(const old of before.cases){
      const current=after.cases.find(c=>c.id===old.id)!;
      const rr=revisions.filter(r=>r.caseId===old.id);
      if(!rr.length)expect(current,old.id).toEqual(old);
      expect(current.decisionNodes.map(n=>n.id)).toEqual(old.decisionNodes.map(n=>n.id));
      for(const n of old.decisionNodes)if(!rr.some(r=>r.nodeId===n.id))expect(current.decisionNodes.find(x=>x.id===n.id),n.id).toEqual(n);
    }
    expect(syntheticClinicalReleaseSchema.safeParse(after).success).toBe(true);
  });
  it("freezes both independently passed cases and all clinical approvals exactly",()=>{
    for(const id of ["B2B06","B2B10"]){const p=capture.packet.find(p=>p.id===id)!;expect(after.cases.find(c=>c.id===p.caseId)).toEqual(before.cases.find(c=>c.id===p.caseId));}
    expect(clone(QUESTION_QUALITY_CLINICAL_APPROVALS)).toEqual(capture.approvals);
    for(const [path,hash]of Object.entries(capture.files).filter(([p])=>/question-bank-batch2a|question-quality-.*20261102|clinical-exhibits\/batch2a/.test(p)))expect(createHash("sha256").update(readFileSync(new URL("../../../"+path,import.meta.url))).digest("hex"),path).toBe(hash);
  });
  it("retains old cards and separately versions the changed scored decisions",()=>{
    expect(concepts).toHaveLength(31);expect(after.concepts.slice(0,before.concepts.length)).toEqual(before.concepts);
    for(const c of concepts){expect(before.concepts.some(p=>p.id===c.previousConceptId)).toBe(true);expect(c.reviewStatus).toBe("needs_clinician_review");expect(c.lastClinicianReview).toBeNull();expect(c.versioningReason.length).toBeGreaterThan(40);}
    expect(revisions.find(r=>r.auditId==="B2B18")!.question.conceptId).toBe(revisions.find(r=>r.auditId==="B2B29")!.question.conceptId);
    expect(revisions.find(r=>r.auditId==="B2B20")!.question.conceptId).toBe(revisions.find(r=>r.auditId==="B2B38")!.question.conceptId);
    expect(revisions.find(r=>r.auditId==="B2B19")!.clinicalBinding).toMatchObject({previousKeyServiceId:"service.ultrasound",nextKeyServiceId:null});
  });
  it("retains exact existing gates and all old timing rows",()=>{
    expect(ANSWER_CHOICE_TIMING_REGISTRY.slice(0,oldTimings.length)).toEqual(oldTimings);
    expect(ANSWER_CHOICE_TIMING_REGISTRY.slice(oldTimings.length,oldTimings.length+timings.length)).toEqual(timings);
    expect(timings).toHaveLength(38);
    for(const r of revisions)expect(r.clinicalBinding.nextResultGate,r.auditId).toEqual(r.clinicalBinding.previousResultGate);
    expect(revisions.filter(r=>r.clinicalBinding.nextResultGate).map(r=>r.auditId)).toEqual(["B2B24","B2B36"]);
  });
  it("keeps new clinical claims mapped, limited, and unapproved",()=>{
    expect(claims).toHaveLength(69);
    for(const c of claims){expect(c.sourceIds.length).toBeGreaterThan(0);expect(c.basisClaimIds.length).toBeGreaterThan(0);expect(c.reviewStatus).toBe("needs_clinician_review");expect(c.lastClinicianReview).toBeNull();expect(c.verificationScope).toContain("no source retrieval");}
  });
  it("registers candidates without manager acceptance or clinical promotion",()=>{
    for(const r of revisions){
      const accepted=QUESTION_SHIP_MANIFEST.accepted.find(a=>a.caseId===r.caseId&&a.nodeId===r.nodeId&&a.questionVariantId===r.questionVariantId);
      const selected=live.cases.find(c=>c.id===r.caseId)?.decisionNodes.find(n=>n.id===r.nodeId);
      if(!accepted)expect(selected?.questionVariantId,r.auditId).not.toBe(r.questionVariantId);
      else expect(selected).toMatchObject({questionVariantId:r.questionVariantId,primaryConceptId:r.question.conceptId});
    }
    expect(revisions.find(r=>r.auditId==="F13")!.previousQuestionVariantId).toBe("question.preoperative-osa.validated-risk-screening.v4.r4");
  });
  it("rejects changed source concept and gate contracts",()=>{
    const cases=clone(before.cases),r=revisions[0]!;
    cases.find(c=>c.id===r.caseId)!.decisionNodes.find(n=>n.id===r.nodeId)!.primaryConceptId="concept.unrelated";
    expect(()=>applyQuestionBankBatch2bRound2Revisions(cases)).toThrow(/binding changed/);
    const gated=clone(before.cases),g=revisions.find(r=>r.auditId==="B2B36")!;
    gated.find(c=>c.id===g.caseId)!.decisionNodes.find(n=>n.id===g.nodeId)!.resultGateAfter!.resultNarrative+=" drift";
    expect(()=>applyQuestionBankBatch2bRound2Revisions(gated)).toThrow(/binding changed/);
  });
  it.each(revisions)("keeps $auditId named, versioned, randomized and fully timed",r=>{
    const cs=after.cases.find(c=>c.id===r.caseId)!,n=cs.decisionNodes.find(n=>n.id===r.nodeId)!;
    expect(n.questionVariantId).not.toBe(r.previousQuestionVariantId);expect(n.shuffleAnswers).toBe(true);expect(n.stem).toContain("{patientName}");
    expect([3,4]).toContain(n.answerChoices.length);expect(n.answerChoices.filter(c=>c.isCorrect)).toHaveLength(1);
    expect(n.answerChoices.some(c=>/\balone\b|\bindividuali[sz]ed\b|\btailored\b/i.test(c.label))).toBe(false);
    for(const profile of [{presentation:cs.presentation,chiefComplaint:cs.chiefComplaint},...(cs.approvedInstantiationProfiles??[])]){expect(profile.presentation).toContain("{patientName}");expect(profile.presentation).toMatch(/\d+-year-old (?:woman|man|person)/);expect(profile.presentation).not.toMatch(/\{ageYears\}|\{sexNoun\}/);expect((profile.chiefComplaint??cs.chiefComplaint??"").trim().split(/\s+/).length).toBeLessThanOrEqual(5);}
    const t=timings.filter(t=>t.caseId===r.caseId&&t.nodeId===r.nodeId&&t.questionVariantId===r.questionVariantId);expect(t).toHaveLength(1);
    if(t[0]!.classification.kind==="test_choices")for(const c of n.answerChoices){const row=t[0]!.classification.choices.find(x=>x.choiceId===c.id)!;expect(row.choiceLabel).toBe(c.label);expect(row.timing).toEqual(r.choiceTimingOverrides![c.id]);}
    expect(r.question.reviewStatus).toBe("needs_clinician_review");
  });
});

import { describe, expect, it } from "vitest";
import { validateSyntheticClinicalRelease } from "../schema";
import { SYNTHETIC_CLINICAL_RELEASE } from "../synthetic-content";
import {
  LEVEL_TWO_ROUTINE_CASE_IDS,
  LEVEL_TWO_RUNTIME_CASES,
} from "./level-two-runtime";
import { ROW_034_QUESTION_VARIANTS } from "./colonic-lipoma";
import { ROW_038_QUESTION_VARIANTS } from "./vitamin-c-collagen-hydroxylation";
import { ROW_039_QUESTION_VARIANTS } from "./gastric-malt-lymphoma";
import { ROW_040_QUESTION_VARIANTS } from "./gastroparesis";
import { ROW_042_QUESTION_VARIANTS } from "./gastric-splenectomy";
import { ROW_049_QUESTION_VARIANTS } from "./peptic-ulcer-bleeding-hemostasis";
import { ROW_111_QUESTION_VARIANTS } from "./distal-cholangiocarcinoma";

const APPROVED_VARIANTS = [
  ...ROW_034_QUESTION_VARIANTS,
  ...ROW_038_QUESTION_VARIANTS,
  ...ROW_039_QUESTION_VARIANTS,
  ...ROW_040_QUESTION_VARIANTS,
  ...ROW_042_QUESTION_VARIANTS,
  ...ROW_049_QUESTION_VARIANTS,
  ...ROW_111_QUESTION_VARIANTS,
];

const EXPECTED_CASE_VARIANTS = [
  ["case.l2.colonic-lipoma.direct.typical-a", ["question.colonic-lipoma.recognition.patient-to-diagnosis.v1", "question.colonic-lipoma.management.patient-to-plan.v1"]],
  ["case.l2.colonic-lipoma.direct.typical-b", ["question.colonic-lipoma.recognition.patient-to-diagnosis.v2", "question.colonic-lipoma.management.patient-to-plan.v2"]],
  ["case.l2.wound-healing.vitamin-c.vitamin-identification.v1", ["question.wound-healing.vitamin-c.vitamin-identification.v1"]],
  ["case.l2.wound-healing.vitamin-c.biochemical-step.v1", ["question.wound-healing.vitamin-c.biochemical-step.v1"]],
  ["case.l2.wound-healing.vitamin-c.mechanism-explanation.v1", ["question.wound-healing.vitamin-c.mechanism-explanation.v1"]],
  ["case.l2.wound-healing.vitamin-c.mechanism-consequence.v1", ["question.wound-healing.vitamin-c.mechanism-consequence.v1"]],
  ["case.l2.gastric-malt.integrated-diagnosis-to-treatment.v1", ["question.gastric-malt.integrated-pathology-diagnosis.v1", "question.gastric-malt.localized-hpylori-positive-initial-treatment.v1"]],
  ["case.l2.gastric-malt.profile-to-followup-boundary.v1", ["question.gastric-malt.pathology-profile-selection.v1", "question.gastric-malt.eradication-response-reassessment.v1"]],
  ["case.l2.gastric-malt.cd20-boundary.v1", ["question.gastric-malt.cd20-alone-boundary.v1"]],
  ["case.l2.gastric-malt.eradication-patient-selection.v1", ["question.gastric-malt.eradication-patient-selection.v1"]],
  ["case.l2.gastroparesis.general-confirmatory-testing.v1", ["question.gastroparesis.general-confirmatory-testing.v1"]],
  ["case.l2.gastroparesis.diabetes-confirmatory-testing.v1", ["question.gastroparesis.diabetes-confirmatory-testing.v1"]],
  ["case.l2.gastroparesis.postsurgical-confirmatory-testing.v1", ["question.gastroparesis.postsurgical-confirmatory-testing.v1"]],
  ["case.l2.gastroparesis.objective-result-selection.v1", ["question.gastroparesis.objective-result-selection.v1"]],
  ["case.l2.gastric-adenocarcinoma.post-endoscopy-splenic-referral.v1", ["question.gastric-adenocarcinoma.post-endoscopy-splenic-referral.v1"]],
  ["case.l2.gastric-adenocarcinoma.spleen-preservation-counseling.v1", ["question.gastric-adenocarcinoma.spleen-preservation-counseling.v1"]],
  ["case.l2.peptic-ulcer-bleeding.visible-vessel-hemostasis.v1", ["question.peptic-ulcer-bleeding.visible-vessel-treat.v1", "question.peptic-ulcer-bleeding.visible-vessel-inadequate-monotherapy.v1"]],
  ["case.l2.peptic-ulcer-bleeding.select-high-risk-stigmata.v1", ["question.peptic-ulcer-bleeding.select-high-risk-stigmata.v1"]],
  ["case.l2.peptic-ulcer-bleeding.clean-base-reverse.v1", ["question.peptic-ulcer-bleeding.clean-base-reverse.v1"]],
  ["case.l2.peptic-ulcer-bleeding.visible-vessel-modality-principle.v1", ["question.peptic-ulcer-bleeding.visible-vessel-modality-principle.v1"]],
  ["case.l2.distal-cholangiocarcinoma.deferred-eus-ercp-to-resection", ["question.distal-cholangiocarcinoma.workup-a.v1", "question.distal-cholangiocarcinoma.management-a.v1"]],
] as const;

describe("Level 2 approved runtime adapter", () => {
  it("admits only exact approved Level 2 cases with bounded decisions and provenance", () => {
    expect(() => validateSyntheticClinicalRelease(SYNTHETIC_CLINICAL_RELEASE)).not.toThrow();
    expect(LEVEL_TWO_ROUTINE_CASE_IDS).toEqual(EXPECTED_CASE_VARIANTS.map(([caseId]) => caseId));
    expect(LEVEL_TWO_RUNTIME_CASES).not.toHaveLength(0);
    for (const clinicalCase of LEVEL_TWO_RUNTIME_CASES) {
      expect(clinicalCase.earliestFacilityStage).toBe(2);
      expect(clinicalCase.releasePointId).toBe("release.l2.endoscopy");
      expect(clinicalCase.decisionNodes.length).toBeLessThanOrEqual(3);
      expect(new Set(clinicalCase.decisionNodes.map((node) => node.primaryConceptId)).size).toBe(clinicalCase.decisionNodes.length);
      expect(clinicalCase.sourceLabels.some((label) => label.startsWith("Clinically approved by Melissa Rowland, MD"))).toBe(true);
      expect(clinicalCase.sourceLabels.some((label) => !label.startsWith("Clinically approved by"))).toBe(true);
      expect(SYNTHETIC_CLINICAL_RELEASE.cases.filter((candidate) => candidate.id === clinicalCase.id)).toHaveLength(1);
    }
  });

  it("copies every admitted approved node verbatim from its exact source variant", () => {
    for (const [caseId, variantIds] of EXPECTED_CASE_VARIANTS) {
      const clinicalCase = LEVEL_TWO_RUNTIME_CASES.find((candidate) => candidate.id === caseId)!;
      expect(clinicalCase.decisionNodes.map((node) => node.questionVariantId)).toEqual(variantIds);
      for (const node of clinicalCase.decisionNodes) {
        const source = APPROVED_VARIANTS.find((variant) => variant.id === node.questionVariantId)!;
        expect(node).toMatchObject({ primaryConceptId: source.conceptId, explanation: source.explanation });
        expect(
          node.stem === source.stem || `${node.currentUpdate ?? clinicalCase.presentation} ${node.stem}` === source.stem,
        ).toBe(true);
        expect(node.answerChoices.map(({ id, label, isCorrect, serviceRequest }) => ({ id, label, isCorrect, serviceId: serviceRequest?.serviceId ?? null }))).toEqual(
